import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Skill Action Bar","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/actionbar.md","filePath":"en/modules/skills/actionbar.md","lastUpdated":0}`),a={name:`en/modules/skills/actionbar.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="skill-action-bar" tabindex="-1">Skill Action Bar <a class="header-anchor" href="#skill-action-bar" aria-label="Permalink to “Skill Action Bar”">​</a></h1><p>The action bar shows skill slot state while the player is in cast mode. It is a good place for the common skill hints at the bottom of the screen, so players open the GUI less often to check bindings.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>Action bar settings live in <code>config.yml</code> under <code>actionbar</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actionbar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Whether the skill action bar is enabled.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Refresh interval in ticks; values below 1 are treated as 1.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  refresh_interval_ticks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Template shown while cast mode is enabled.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_cast_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;Cast Mode&lt;/gold&gt; %slot_1% %slot_2% %slot_3% &lt;gray&gt;Delay:&lt;/gray&gt; %forced_delay%&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Idle template; blank falls back to the source default text instead of disabling the display.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_idle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td><code>actionbar.enabled</code></td><td>boolean</td><td>No</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>Whether the action bar refreshes. When off, no refresh task is started.</td></tr><tr><td><code>actionbar.refresh_interval_ticks</code></td><td>integer</td><td>No</td><td><code>10</code></td><td>≥ 1, values below 1 become 1</td><td>Refresh interval in ticks (20 ticks ≈ 1 second).</td></tr><tr><td><code>actionbar.template_cast_mode</code></td><td>string</td><td>No</td><td><code>&amp;aCast Mode &amp;7| %slot_display%</code></td><td>MiniMessage text</td><td>Template while cast mode is on. Blank or whitespace-only falls back to the built-in default template.</td></tr><tr><td><code>actionbar.template_idle</code></td><td>string</td><td>No</td><td><code>&amp;7Idle</code></td><td>MiniMessage text</td><td>Idle template. Blank or whitespace-only falls back to the built-in default.</td></tr></tbody></table><div class="important custom-block"><p class="custom-block-title custom-block-title-default">IMPORTANT</p><p>The current implementation only pushes the action bar while the player is in cast mode and their profile is loaded: leaving cast mode, or having no loaded profile, skips the refresh entirely, so <code>template_idle</code> is never sent to the player. The key is still parsed and kept as a fallback default.</p></div><h2 id="template-variables" tabindex="-1">Template variables <a class="header-anchor" href="#template-variables" aria-label="Permalink to “Template variables”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>%slot_display%</code></td><td>All slots rendered as one combined string, separated by spaces.</td></tr><tr><td><code>%slot_1%</code> ~ <code>%slot_n%</code></td><td>A single slot&#39;s text. <code>n</code> follows the player&#39;s slot count (<code>slots.default_count</code>); <code>%slot_1%</code> is the slot at index 0.</td></tr><tr><td><code>%forced_delay%</code></td><td>Remaining global forced cast delay, formatted as <code>1.5s</code>; <code>0s</code> when there is none.</td></tr></tbody></table><p>Slot text combines the bound skill, the trigger display name, cooldown state, and empty-slot state. An empty slot uses <code>gui.slot_empty_short</code> from the language file; trigger names come from <code>triggers.&lt;id&gt;.display_name</code>, and an unbound trigger uses <code>gui.trigger_unbound_short</code>.</p><h2 id="forced-delay" tabindex="-1">Forced delay <a class="header-anchor" href="#forced-delay" aria-label="Permalink to “Forced delay”">​</a></h2><p><code>cast_timing</code> controls the global forced delay written after a successful cast; the remaining time is shown through <code>%forced_delay%</code> above.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">cast_timing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Global delay after a successful cast, in ticks; 0 disables it.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  forced_global_cast_delay_ticks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td><code>cast_timing.forced_global_cast_delay_ticks</code></td><td>integer</td><td>No</td><td><code>0</code></td><td>≥ 0, negatives become 0</td><td>Global forced delay written after a successful cast, in ticks. During the delay a new cast attempt fails with <code>cast.forced_delay</code>. <code>0</code> disables it.</td></tr></tbody></table><h2 id="relationship-to-cast-mode" tabindex="-1">Relationship to cast mode <a class="header-anchor" href="#relationship-to-cast-mode" aria-label="Permalink to “Relationship to cast mode”">​</a></h2><p>The action bar only refreshes while cast mode is on. The entry key, the enable switch, and the rejoin restore policy are controlled by <code>config.yml &gt; cast_mode</code>, see <a href="./triggers.html#cast-mode">Triggers · Cast mode</a>.</p><ul><li>Active triggers only listen to server-visible actions (left/right click, Q, number keys) while cast mode is on.</li><li>With <code>cast_mode.restore_last_state_on_join: true</code>, a rejoining player gets their previous cast mode state back, and with it the action bar refresh.</li></ul><h2 id="recommended-templates" tabindex="-1">Recommended templates <a class="header-anchor" href="#recommended-templates" aria-label="Permalink to “Recommended templates”">​</a></h2><h3 id="compact" tabindex="-1">Compact <a class="header-anchor" href="#compact" aria-label="Permalink to “Compact”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actionbar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_cast_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;Cast&lt;/gold&gt; %slot_display%&quot;</span></span></code></pre></div><p>Suits servers with few skill slots.</p><h3 id="with-delay-hint" tabindex="-1">With delay hint <a class="header-anchor" href="#with-delay-hint" aria-label="Permalink to “With delay hint”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actionbar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_cast_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;Cast Mode&lt;/gold&gt; %slot_1% %slot_2% %slot_3% &lt;gray&gt;Delay:&lt;/gray&gt; %forced_delay%&quot;</span></span></code></pre></div><p>Suits servers that enable <code>cast_timing.forced_global_cast_delay_ticks</code>.</p><h2 id="design-notes" tabindex="-1">Design notes <a class="header-anchor" href="#design-notes" aria-label="Permalink to “Design notes”">​</a></h2><ul><li>If the server already shows combat, region, or quest text on the action bar, plan display priority across them.</li><li>With many slots, prefer <code>%slot_display%</code> or split the display into groups so the line does not grow too long.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li>Nothing shows: check <code>actionbar.enabled</code>, whether the player is in cast mode, and whether their profile has loaded.</li><li>Slots look empty: check that the player owns the skills, that slots are bound, and that skill sources are synced.</li><li>The delay never changes: check <code>cast_timing.forced_global_cast_delay_ticks</code> and whether successful casts write the delay.</li><li>Conflicts with another action bar plugin: adjust <code>actionbar.refresh_interval_ticks</code>.</li></ul>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};